import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // Load primary gear mesh from GLB
  const primaryGearGLB = ctx.glbLoader.load(config.meshUrl);
  const primaryGear = primaryGearGLB.scene.clone();

  // Scale primary gear to 1.6-unit diameter
  primaryGear.scale.set(1.6, 1.6, 1.6);
  primaryGear.position.set(0, 0, 0);

  // Create secondary gear instance (0.9-unit diameter, offset)
  const secondaryGear = primaryGear.clone();
  secondaryGear.scale.set(0.9, 0.9, 0.9);
  secondaryGear.position.set(1.15, 0.35, -0.1);

  // Apply machined-steel PBR material to both gears
  const gearMaterial = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    anisotropy: 0.7,
  });
  disposables.push(gearMaterial);

  primaryGear.traverse(child => {
    if (child instanceof THREE.Mesh) {
      child.material = gearMaterial;
    }
  });

  secondaryGear.traverse(child => {
    if (child instanceof THREE.Mesh) {
      const mat = gearMaterial.clone();
      disposables.push(mat);
      child.material = mat;
    }
  });

  root.add(primaryGear);
  root.add(secondaryGear);

  // Jewel pivot sphere at primary hub
  const jewelGeometry = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMaterial = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#ff2a38'),
    transmission: 0.6,
    ior: 1.76,
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.8,
  });
  const jewel = new THREE.Mesh(jewelGeometry, jewelMaterial);
  root.add(jewel);

  disposables.push(jewelGeometry, jewelMaterial);

  // Arbor shafts through hubs
  const arborGeometry = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 32);
  const arborMaterial = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#16161d'),
  });
  disposables.push(arborGeometry, arborMaterial);

  const arbor1 = new THREE.Mesh(arborGeometry, arborMaterial);
  root.add(arbor1);

  const arborMat2 = arborMaterial.clone();
  disposables.push(arborMat2);
  const arbor2 = new THREE.Mesh(arborGeometry, arborMat2);
  arbor2.position.set(1.15, 0.35, -0.1);
  root.add(arbor2);

  // Contact shadow ellipse
  const shadowGeometry = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMaterial = new THREE.MeshBasicMaterial({
    color: new THREE.Color('#000000'),
    opacity: 0.5,
    transparent: true,
  });
  const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -1.2, 0.01);
  root.add(shadow);

  disposables.push(shadowGeometry, shadowMaterial);

  // Backdrop plane with radial gradient
  const size = 256;
  const data = new Uint8Array(size * size * 3);

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const cx = size / 2;
      const cy = size / 2;
      const distance = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
      const maxDistance = Math.sqrt(cx * cx + cy * cy);
      const t = Math.min(1, distance / maxDistance);

      let r, g, b;
      if (t < 0.65) {
        const t1 = t / 0.65;
        r = Math.round(0x0b + (0x10 - 0x0b) * t1);
        g = Math.round(0x0b + (0x10 - 0x0b) * t1);
        b = Math.round(0x10 + (0x17 - 0x10) * t1);
      } else {
        const t2 = (t - 0.65) / 0.35;
        r = Math.round(0x10 + (0x16 - 0x10) * t2);
        g = Math.round(0x10 + (0x16 - 0x10) * t2);
        b = Math.round(0x17 + (0x1d - 0x17) * t2);
      }

      const idx = (y * size + x) * 3;
      data[idx] = Math.max(0, Math.min(255, r));
      data[idx + 1] = Math.max(0, Math.min(255, g));
      data[idx + 2] = Math.max(0, Math.min(255, b));
    }
  }

  const backdropTexture = new THREE.DataTexture(data, size, size, THREE.RGBFormat);
  backdropTexture.needsUpdate = true;
  disposables.push(backdropTexture);

  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdropMaterial = new THREE.MeshBasicMaterial({ map: backdropTexture });
  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -3;
  root.add(backdrop);

  disposables.push(backdropGeometry, backdropMaterial);

  // Fog for depth hint
  root.fog = new THREE.Fog(new THREE.Color('#0b0b10'), 5, 11);

  // Text rendering
  const textGroup = new THREE.Group();

  const headlineText = ctx.fontAtlas.createText("The going train", {
    fontSize: 68,
    fontFamily: 'Lora',
    fontWeight: '600',
    color: new THREE.Color('#e8ecf2'),
  });
  headlineText.position.y = -1.7;
  headlineText.position.z = 0.1;
  textGroup.add(headlineText);

  const captionText = ctx.fontAtlas.createText("34 COMPONENTS / HAND-FINISHED", {
    fontSize: 18,
    fontFamily: 'JetBrains Mono',
    fontWeight: '400',
    color: new THREE.Color('#e8ecf2'),
  });
  captionText.position.y = -2.1;
  captionText.position.z = 0.1;
  textGroup.add(captionText);

  root.add(textGroup);

  // Gear rotation: primary 0.08 rad/s, secondary -0.142 rad/s (phase-locked 16:9 ratio)
  const primaryDuration = (Math.PI * 2) / 0.08;
  const secondaryDuration = (Math.PI * 2) / 0.142;

  const primaryTimeline = gsap.timeline({ repeat: -1 });
  primaryTimeline.to(primaryGear.rotation, 
    { z: `+=${Math.PI * 2}`, duration: primaryDuration, ease: 'none' }, 
    0);
  timelines.push(primaryTimeline);

  const secondaryTimeline = gsap.timeline({ repeat: -1 });
  secondaryTimeline.to(secondaryGear.rotation,
    { z: `-=${Math.PI * 2}`, duration: secondaryDuration, ease: 'none' },
    0);
  timelines.push(secondaryTimeline);

  // Apply orbit cinematic primitive
  if (ctx.primitives && typeof ctx.primitives.orbit === 'function') {
    ctx.primitives.orbit(root, { speed: 0.08, radius: 0.2 });
  }

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(obj => {
      if (obj && typeof obj.dispose === 'function') {
        obj.dispose();
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
